//! Cursor glyphs generated by cursorcraft (https://github.com/bobtherobot/cursorcraft) from
//! original SVG designs. [`GENERATED`] says which cursors use them; the rest keep their hand-drawn
//! glyph in the parent module. The `/update-cursors` skill writes this file and `cursors.toml`
//! beside it, whose test keeps the two in step: don't edit the generated `const`s by hand.

use super::{HALO, INK, Ink};
use egui::{Pos2, Shape, Stroke, vec2};
use vectorcraft_tools::Cursor;

/// The cursors drawn with a generated glyph.
pub(super) const GENERATED: &[(Cursor, &Glyph)] = &[];

/// The generated glyph for cursor `c`, if it has one.
pub(super) fn generated(c: Cursor) -> Option<&'static Glyph> {
    GENERATED.iter().find(|(k, _)| *k == c).map(|&(_, g)| g)
}

/// A cursor glyph generated by cursorcraft from an SVG: its parts in drawing order, in points
/// relative to the hotspot. Drawn by [`draw_glyph`]. `svg` and `fp` name the SVG and its
/// fingerprint, which VectorCraft's sync record test checks.
pub(crate) struct Glyph {
    #[allow(dead_code, reason = "read by the sync record's test")]
    pub svg: &'static str,
    #[allow(dead_code, reason = "read by the sync record's test")]
    pub fp: &'static str,
    pub parts: &'static [GlyphPart],
}

#[expect(dead_code, reason = "until the first sync wires a glyph")]
pub(crate) enum GlyphPart {
    /// A filled shape: `tris` triangulates a concave shape, empty for a convex one.
    Fill { points: &'static [(f32, f32)], tris: &'static [[u16; 3]], white: bool },
    /// A stroked line, open or closed.
    Stroke { points: &'static [(f32, f32)], closed: bool, width: f32, white: bool },
}

/// The white halo under the ink, as the hand-drawn glyphs have it: a 3-point outline under a
/// fill (inked with a 1-point outline), and a stroke 1.8 points wider under a stroke.
const GLYPH_FILL_HALO: f32 = 3.0;
const GLYPH_STROKE_HALO: f32 = 1.8;

/// Draw a generated glyph with its hotspot at `o`: every halo first, then every part in order,
/// so no part's halo cuts through another's ink.
pub(super) fn draw_glyph(p: &mut Ink, o: Pos2, g: &Glyph) {
    let at = |pts: &[(f32, f32)]| pts.iter().map(|&(x, y)| o + vec2(x, y)).collect::<Vec<_>>();
    for part in g.parts {
        match part {
            GlyphPart::Fill { points, white: false, .. } => p.add(Shape::closed_line(at(points), Stroke::new(GLYPH_FILL_HALO, HALO))),
            GlyphPart::Stroke { points, closed, width, white: false } => {
                let stroke = Stroke::new(width + GLYPH_STROKE_HALO, HALO);
                p.add(if *closed { Shape::closed_line(at(points), stroke) } else { Shape::line(at(points), stroke) });
            }
            _ => {}
        }
    }
    for part in g.parts {
        match part {
            GlyphPart::Fill { points, tris, white } => {
                let colour = if *white { HALO } else { INK };
                let pts = at(points);
                if tris.is_empty() {
                    p.add(Shape::convex_polygon(pts.clone(), colour, Stroke::NONE));
                } else {
                    let mut mesh = egui::Mesh::default();
                    for &pos in &pts {
                        mesh.colored_vertex(pos, colour);
                    }
                    for t in *tris {
                        // Generated data: every index is below the point count (a test checks).
                        if t.iter().all(|&i| usize::from(i) < pts.len()) {
                            mesh.add_triangle(u32::from(t[0]), u32::from(t[1]), u32::from(t[2]));
                        }
                    }
                    p.add(Shape::mesh(mesh));
                }
                if !white {
                    p.add(Shape::closed_line(pts, Stroke::new(1.0, INK)));
                }
            }
            GlyphPart::Stroke { points, closed, width, white } => {
                let stroke = Stroke::new(*width, if *white { HALO } else { INK });
                p.add(if *closed { Shape::closed_line(at(points), stroke) } else { Shape::line(at(points), stroke) });
            }
        }
    }
}

// Generated glyphs (cursorcraft gen), written by /update-cursors.

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    #[derive(serde::Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Record {
        cursorcraft: String,
        #[serde(default)]
        cursor: Vec<Entry>,
    }

    #[derive(serde::Deserialize)]
    #[serde(deny_unknown_fields)]
    struct Entry {
        svg: String,
        svg_fp: Option<String>,
        info_fp: String,
        status: Status,
        #[serde(default)]
        slots: Vec<Cursor>,
        note: String,
    }

    #[derive(serde::Deserialize, PartialEq, Debug)]
    #[serde(rename_all = "lowercase")]
    enum Status {
        Wired,
        Skipped,
        Needed,
        Obsolete,
    }

    fn record() -> Record {
        toml::from_str(include_str!("cursors.toml")).expect("cursors.toml parses")
    }

    #[test]
    fn the_record_names_its_source_and_each_svg_once() {
        let r = record();
        assert!(!r.cursorcraft.is_empty());
        let mut seen = HashMap::new();
        for e in &r.cursor {
            assert!(seen.insert(e.svg.as_str(), ()).is_none(), "{} recorded twice", e.svg);
            assert!(!e.note.trim().is_empty() && e.info_fp.len() == 8, "{}: note and info_fp", e.svg);
            assert_eq!(e.svg_fp.is_some(), e.status != Status::Needed, "{}: svg_fp is set exactly when drawn", e.svg);
            assert_eq!(e.slots.is_empty(), matches!(e.status, Status::Skipped | Status::Obsolete), "{}: slots", e.svg);
        }
    }

    #[test]
    fn every_generated_glyph_is_recorded_as_wired_with_its_fingerprint() {
        let r = record();
        for (c, g) in GENERATED {
            let e = r.cursor.iter().find(|e| e.svg == g.svg).unwrap_or_else(|| panic!("{c:?}: {} not in cursors.toml", g.svg));
            assert_eq!(e.status, Status::Wired, "{}", g.svg);
            assert_eq!(e.svg_fp.as_deref(), Some(g.fp), "{}: regenerate it (stale or hand-edited)", g.svg);
            assert!(e.slots.contains(c), "{}: {c:?} isn't in its recorded slots", g.svg);
        }
    }

    #[test]
    fn every_wired_entry_has_exactly_its_slots_in_generated() {
        for e in record().cursor.iter().filter(|e| e.status == Status::Wired) {
            let wired: Vec<Cursor> = GENERATED.iter().filter(|(_, g)| g.svg == e.svg).map(|&(c, _)| c).collect();
            assert_eq!(wired.len(), e.slots.len(), "{}: GENERATED has {wired:?}, record has {:?}", e.svg, e.slots);
            assert!(e.slots.iter().all(|s| wired.contains(s)), "{}: GENERATED has {wired:?}, record has {:?}", e.svg, e.slots);
        }
    }

    #[test]
    fn no_cursor_has_two_generated_glyphs() {
        for (i, (c, _)) in GENERATED.iter().enumerate() {
            assert!(!GENERATED[..i].iter().any(|(k, _)| k == c), "{c:?} appears twice in GENERATED");
        }
    }

    #[test]
    fn generated_glyph_data_is_well_formed() {
        for (c, g) in GENERATED {
            assert!(!g.parts.is_empty(), "{c:?}");
            for part in g.parts {
                let (GlyphPart::Fill { points, .. } | GlyphPart::Stroke { points, .. }) = part;
                assert!(points.iter().all(|(x, y)| x.is_finite() && y.is_finite() && x.abs() < 64.0 && y.abs() < 64.0), "{c:?}");
                if let GlyphPart::Fill { tris, .. } = part {
                    assert!(tris.iter().flatten().all(|&i| usize::from(i) < points.len()), "{c:?}: triangle index out of range");
                }
            }
        }
    }
}
